"""凭据配置 API — Token 热加载（无需重启）。

PUT    /api/v1/credentials — 配置 Token
GET    /api/v1/credentials — 查看凭据状态（脱敏）
DELETE /api/v1/credentials — 清除凭据
"""
import logging
from datetime import datetime

import httpx
from fastapi import APIRouter
from pydantic import BaseModel

logger = logging.getLogger('agent.server.credentials')

router = APIRouter(prefix='/credentials', tags=['credentials'])


class CredentialPutRequest(BaseModel):
    token: str


def _mask_token(token: str) -> str:
    """脱敏显示密钥（前8+后4字符）。"""
    if not token:
        return ''
    if len(token) <= 16:
        return '****'
    return token[:8] + '****' + token[-4:]


@router.put('')
async def configure_credentials(req: CredentialPutRequest):
    """配置 Token（热加载，无需重启）。

    1. 用 token 向平台 validate API 验证有效性
    2. 验证通过 → 获取 agent_id、platform_url、ws_url
    3. 写入 SQLite credentials 表
    4. 更新内存 config（热加载）
    """
    from agent_runtime.server.app import get_agent_app
    app = get_agent_app()
    if not app:
        return {'error': 'Agent 未初始化'}

    token_str = req.token.strip()
    if not token_str:
        return {'error': 'token 不能为空'}

    # 确定平台 validate API 地址
    backend_url = app.config.backend_url.rstrip('/') if app.config.backend_url else ''
    if not backend_url:
        return {
            'error': '未配置平台地址，请先设置 CHIIP_BACKEND_URL 或在 config.yaml 中配置 platform 段'
        }
    validate_url = '%s/api/v1/agent-tokens/validate/' % backend_url

    # 向平台验证 token
    try:
        async with httpx.AsyncClient(timeout=10) as client:
            resp = await client.post(validate_url, json={'token': token_str})
            result = resp.json()
    except Exception as e:
        logger.warning('平台验证请求失败: %s', e)
        return {'error': '平台验证请求失败: %s' % e}

    if not result.get('valid'):
        reason = result.get('reason', 'unknown')
        reason_map = {
            'invalid': '密钥无效',
            'revoked': '密钥已撤销',
            'expired': '密钥已过期',
            'missing_token': '未提供密钥',
        }
        return {'error': reason_map.get(reason, '密钥验证失败: %s' % reason)}

    agent_id = result.get('agent_id', '')
    platform_url = result.get('platform_url', backend_url)
    ws_url = result.get('ws_url', '')
    expires_at = result.get('expires_at', '')

    # 写入 SQLite
    db = app.db
    db.set_credential('token', token_str)
    db.set_credential('agent_id', agent_id)
    db.set_credential('platform_url', platform_url)
    db.set_credential('ws_url', ws_url)
    db.set_credential('configured_at', datetime.now().isoformat())

    # 热加载到内存
    app.config.ws_token = token_str
    if agent_id:
        app.config.agent_id = agent_id
    if platform_url:
        app.config.backend_url = platform_url.rstrip('/')
    if ws_url:
        app.config.ws_url = ws_url.rstrip('/')
    app.config.has_credentials = True

    logger.info('凭据已配置: agent_id=%s, expires=%s', agent_id, expires_at)

    return {
        'status': 'ok',
        'agent_id': agent_id,
        'platform_url': platform_url,
        'ws_url': ws_url,
        'expires_at': expires_at,
    }


@router.get('')
async def get_credentials():
    """查看凭据状态（脱敏显示）。"""
    from agent_runtime.server.app import get_agent_app
    app = get_agent_app()
    if not app:
        return {'error': 'Agent 未初始化'}

    token = app.config.ws_token
    configured = bool(token)

    data = {
        'configured': configured,
        'agent_id': app.config.agent_id if configured else '',
        'token_masked': _mask_token(token) if configured else '',
        'platform_url': app.config.backend_url or '',
        'ws_url': app.config.ws_url or '',
    }

    # 从 SQLite 获取配置时间
    configured_at = app.db.get_credential('configured_at')
    if configured_at:
        data['configured_at'] = configured_at

    return data


@router.delete('')
async def clear_credentials():
    """清除凭据（断开平台连接）。"""
    from agent_runtime.server.app import get_agent_app
    app = get_agent_app()
    if not app:
        return {'error': 'Agent 未初始化'}

    # 清除 SQLite
    app.db.clear_credentials()

    # 清除内存
    app.config.ws_token = ''
    app.config.has_credentials = False

    # 如果当前在 collaborative/order 模式，切回 local
    if app.config.run_mode in ('collaborative', 'order'):
        app.config.run_mode = 'local'
        app.run_mode = 'local'
        # 断开 WS 连接
        if app.ws_client:
            try:
                app.ws_client.stop()
            except Exception:
                pass
            app.ws_client = None

    logger.info('凭据已清除')
    return {'status': 'cleared'}
